let state,brandConfig={companyName:'示例公司',logoUrl:null},route=location.hash.slice(1)||'home',search='',depFilter='',statusFilter='',upload=null,chosen=new Set(),edits={},replaceTarget=null,ids=[],preview=null,previewIndex=1,toastTimer;
