async function api(path,body){const o={method:body===undefined?'GET':'POST',headers:{'X-Requested-With':'PPTStudio'}};if(body!==undefined){if(body instanceof FormData)o.body=body;else{o.body=JSON.stringify(body);o.headers['Content-Type']='application/json';}}if(path==='/api/imports')o.headers['Idempotency-Key']=upload.requestKey;const r=await fetch(path,o);const d=await r.json().catch(()=>null);if(!r.ok)throw new Error(d?.message||(r.status===401?'登录已失效，请刷新后重新登录':r.status===429?'操作频繁，请稍后重试':'请求失败 '+r.status));return d;}
