function detail(id,review=false,versionId=null){
 const p=state.pages.find(p=>p.id===id),v=p.versions.find(v=>v.id===versionId)||(maintain(p)?last(p):pub(p)),old=pub(p);
 const pending=p.versions.some(v=>v.status==='pending'),editable=maintain(p)&&!review;
 editingVersion=v.id;
 const visuals='<div class="detail-preview-head"><span>'+versionLabel(v)+' · '+E(v.title)+'</span>'+btn('zoom-page','放大查看','small','eye',id+':'+v.id)+'</div><img class="modal-image" src="'+url(v)+'" alt="'+E(v.title)+'">'+
 (old&&old.id!==v.id?'<details class="previous-preview"><summary>对照当前发布版本 V'+old.number+'</summary>'+image(url(old),old.title)+'</details>':'')+
 '<p class="field-note">WPS 高清预览 · 编辑右侧信息不会修改 PPT 内部文字、图片或图表。</p>';
 const fields=field('页面标题','edit-title',v.title,'text','maxlength="100"')+field('所属章节','edit-chapter',v.chapter,'text','maxlength="40"')+field('标签','edit-tags',v.tags)+select('适用场景','edit-scenario',scenes.map(s=>[s,s]),v.scenario)+'<label>更新说明<textarea id="edit-note">'+E(versionId&&v.id!==last(p).id?'从 '+versionLabel(v)+' 恢复内容':v.note)+'</textarea></label>';
 const history='<details class="detail-history"><summary>版本记录与草稿 · '+p.versions.filter(x=>x.status==="approved").length+' 个已发布版本</summary>'+p.versions.slice().reverse().map(x=>'<div class="version-row"><div><strong>'+versionLabel(x)+'</strong><p class="muted small-text">'+time(x.created)+' '+E(x.reviewNote)+'</p><a href="/api/pages/'+p.id+'/versions/'+x.id+'/download">下载可编辑 PPTX</a></div>'+(maintain(p)?btn('restore-version','恢复','small','clock',p.id+':'+x.id):'')+'</div>').join('')+'</details>';
 const buttons=review?btn('reject','驳回','danger','close',id)+btn('approve','审核并发布','primary','check',id):
 editable?btn('save-edit','保存草稿','','file',id)+btn('save-edit-submit','保存并提交审核','primary','check',id):
 pending&&admin()?btn('review-detail','进入审核','primary','check',id):'';
 modal(v.title,'<div class="page-detail-layout"><section class="page-detail-preview">'+visuals+'<div class="detail-preview-bottom">'+history+(maintain(p)?'<div class="detail-status-panel"><span class="status-caption">状态</span>'+badge(p.enabled?'已启用':'已停用',p.enabled?'approved':'red')+btn('settings','设置','small','rule',id)+'</div>':'')+'</div></section><aside class="page-detail-editor"><div class="detail-meta">'+badge(statuses[v.status],v.status)+badge(dep(p.departmentId))+'</div>'+
 (editable?'<p class="field-note">'+(pending?'待审核内容可以继续修改。保存草稿将撤回审核；保存并提交审核会重新提交最新内容。':'保存只更新草稿，审核通过后才升级正式版本。')+'</p>':!maintain(p)?'<p class="field-note">你拥有查看权限，内容由所属部门维护。</p>':'')+
 '<fieldset class="form-grid detail-fields" '+(editable?'':'disabled')+'>'+fields+'</fieldset>'+
 (review?'<label>审核意见<textarea id="review-note" placeholder="发布说明或驳回原因"></textarea></label>':'')+
 '<div class="detail-save-actions">'+buttons+'</div></aside></div>');
 mr.querySelector('.modal')?.classList.add('page-detail-modal');
}
