function go(r){if(location.hash==='#'+r){route=r;render();}else location.hash=r;}
async function uploadFile(file){if(!file)return;if(!file.name.toLowerCase().endsWith('.pptx'))throw new Error('请选择 .pptx 文件');const form=new FormData();form.append('file',file);form.append('departmentId',val('upload-department')||state.user.departmentId);modal('正在解析 PPT','<div class="progress-box"><span class="loading"></span><h3>'+E(file.name)+'</h3><p class="muted">正在提取页面与可编辑对象…</p></div>');try{upload=await api('/api/uploads',form);upload.requestKey=crypto.randomUUID();chosen=new Set();edits={};await refresh();upload.suggestions={};for(const slide of upload.slides){const match=state.pages.find(p=>maintain(p)&&p.departmentId===upload.departmentId&&(last(p).title===slide.title.slice(0,100)||(last(p).slideIndex===slide.index&&state.uploads.find(u=>u.id===last(p).uploadId)?.name===upload.name)));if(match)upload.suggestions[slide.index]=match.id;}render();if(replaceTarget)toast('请勾选用于替换的新页面');}finally{close();}}
async function doImport(submit){const items=[...chosen].sort((a,b)=>a-b).map(i=>{const ed=edits[i]||{},target=state.pages.find(p=>p.id===ed.target);return {slideIndex:i,title:ed.title??upload.slides[i-1].title.slice(0,100),chapter:upload.chapter||'公司概况',scenario:upload.scenario||'通用',tags:upload.tags||'',note:upload.note||'',targetPageId:target?.id||null,expectedRevision:target?.revision||0};});await api('/api/imports',{uploadId:upload.id,items,submit});upload=null;chosen.clear();replaceTarget=null;await refresh();go('library');toast(submit?'草稿已提交审核':'已保存为草稿');}
async function generate(){modal('正在生成演示文稿','<div class="progress-box"><span class="loading"></span><h3 id="job-message">正在校验必选规则…</h3><p class="muted">组装正文、生成目录和章节页，保留可编辑对象。</p></div>');try{const r=await api('/api/generations',{...compose,pageIds:ids,chapters:outlinePayload()});for(let i=0;i<300;i++){const j=await api('/api/jobs/'+r.jobId);if($('#job-message'))$('#job-message').textContent=j.message;if(j.status==='failed')throw new Error(j.error);if(j.status==='done'){await refresh();render();genPreview(state.generations.find(g=>g.id===r.jobId));return;}await new Promise(r=>setTimeout(r,1000));}throw new Error('任务仍在运行，请稍后查看生成历史，不要重复提交。');}catch(e){close();throw e;}}
async function action(a,id){if(a.startsWith('go-')){go(a.slice(3));return;}switch(a){
case'save-brand-name':{const result=await api('/api/brand/name',{companyName:val('brand-company-name')});brandConfig=result;await refresh();render();toast('公司名称已更新');break;}
case'choose-brand-logo':$('#brand-logo-file').click();break;
case'reset-brand-logo':brandConfig=await api('/api/brand/logo/delete',{});await refresh();render();toast('已恢复默认 Logo');break;
case'choose-brand-logo':$('#brand-logo-file').click();break;
case'reset-brand-logo':{brandConfig=await api('/api/brand/logo/delete',{});await refresh();render();toast('已恢复默认 Logo');break;}
case'menu':$('.sidebar').classList.toggle('open');break;case'close':close();break;case'logout':await api('/api/logout',{});state=null;await start();break;
case'detail':detail(id);break;case'zoom-page':{const [pid,vid]=id.split(':'),p=state.pages.find(p=>p.id===pid),v=p.versions.find(v=>v.id===vid);window.open(url(v),'_blank','noopener');break;}case'review-detail':detail(id,true);break;case'pick-file':$('#file-input')?.click();break;
case'reset-upload':upload=null;chosen.clear();render();break;case'replace':replaceTarget=id;upload=null;go('upload');toast('上传更新文件后勾选需要替换的页面');break;
case'toggle-slide':{const i=Number(id);if(chosen.has(i))chosen.delete(i);else{chosen.add(i);if(replaceTarget&&!Object.values(edits).some(x=>x.target===replaceTarget))edits[i]={...edits[i],target:replaceTarget};}render();break;}
case'accept-suggestion':edits[id]={...edits[id],target:upload.suggestions[id]};render();break;
case'all-slides':upload.slides.forEach(s=>chosen.add(s.index));render();break;case'no-slides':chosen.clear();render();break;
case'import-submit':await doImport(true);break;case'import-draft':await doImport(false);break;
case'submit-page':{const p=state.pages.find(p=>p.id===id);await api('/api/pages/'+id+'/submit',{revision:p.revision});close();await refresh();render();toast('已提交审核');break;}
case'approve':case'reject':{const p=state.pages.find(p=>p.id===id),note=val('review-note');if(a==='reject'&&!note.trim())throw new Error('请填写驳回原因');await api('/api/pages/'+id+'/review',{revision:p.revision,versionId:last(p).id,approve:a==='approve',note});close();await refresh();render();toast(a==='approve'?'已审核发布':'已驳回该版本');break;}

case'edit-page':editPage(id);break;
case'restore-version':{const [pageId,versionId]=id.split(':');editPage(pageId,versionId);break;}
case'save-edit':case'save-edit-submit':{const p=state.pages.find(p=>p.id===id);await api('/api/pages/'+id+'/versions',{revision:p.revision,versionId:editingVersion,title:val('edit-title'),chapter:val('edit-chapter'),tags:val('edit-tags'),scenario:val('edit-scenario'),note:val('edit-note'),submit:a==='save-edit-submit'});await refresh();render();detail(id);toast(a==='save-edit-submit'?'草稿已提交审核':'已保存草稿');break;}

case'settings':settings(id);break;case'save-settings':{const p=state.pages.find(p=>p.id===id);await api('/api/pages/'+id+'/settings',{revision:p.revision,enabled:$('#setting-enabled').checked,required:$('#setting-required')?.checked??p.required,departmentRequired:$('#setting-department')?.checked??p.departmentRequired,requiredScenario:admin()?val('setting-scenario'):p.requiredScenario});close();await refresh();render();toast('设置已保存');break;}
case'add-page':if(!ids.includes(id))ids.push(id);render();break;case'remove-page':if(required().includes(id)){toast('必选页面不能移除');break;}ids=ids.filter(x=>x!==id);render();break;
case'move-up':case'move-down':{syncOutline();const c=outline.find(c=>c.pageIds.includes(id));const i=c.pageIds.indexOf(id),j=i+(a==='move-up'?-1:1);if(j>=0&&j<c.pageIds.length)[c.pageIds[i],c.pageIds[j]]=[c.pageIds[j],c.pageIds[i]];render();break;}
case'generate':await generate();break;case'save-plan':if(!resolved().length)throw new Error('请先选择内容');modal('保存生成方案',field('方案名称','plan-name','','text','maxlength="80"'),btn('confirm-plan','保存方案','primary','check'),true);break;
case'confirm-plan':await api('/api/plans',{name:val('plan-name'),title:compose.title,scenario:compose.scenario,pageIds:ids,templateId:compose.templateId,chapters:outlinePayload(),options:compose.options});close();await refresh();toast('方案已保存');break;
case'reuse-plan':{const p=state.plans.find(p=>p.id===id);ids=p.pageIds.slice();outline=(p.chapters||[]).map(c=>({...c,pageIds:[...c.pageIds]}));compose={...compose,title:p.title,scenario:p.scenario,templateId:p.templateId,options:p.options||{numberStyle:'arabic',tocPageNumbers:true,pageNumbers:false}};go('compose');toast('已载入方案，将使用最新发布版本');break;}
case'preview-generation':genPreview(state.generations.find(g=>g.id===id));break;case'prev':genPreview(preview,previewIndex-1);break;case'next':genPreview(preview,previewIndex+1);break;
case'confirm-download':await api('/api/generations/'+id+'/confirm',{hash:preview.hash});window.location.assign('/api/generations/'+id+'/download');await refresh();render();toast('已确认，开始下载 PPTX');break;

case'delete-template':{const t=state.templates.find(t=>t.id===id);modal('删除模板版本','<div class="form-grid"><p>确定删除 <strong>'+E(t.name)+'</strong> 吗？</p><p class="field-note">删除后将从模板列表和生成选项移除。源文件与历史生成记录保留，引用此版本的已保存方案需要重新选择模板。</p></div>',btn('close','取消')+btn('confirm-delete-template','确认删除','danger','close',id),true);break;}
case'confirm-delete-template':await api('/api/templates/'+id+'/delete',{});close();await refresh();render();toast('模板版本已删除，历史记录已保留');break;
case'upload-template-previews':originalPreviewDialog(id);break;
case'save-template-previews':{const files=$('#template-preview-files')?.files;if(!files?.length)throw new Error('请先选择PNG图片');const data=new FormData();for(const file of files)data.append('files',file);const result=await api('/api/templates/'+id+'/previews',data);await refresh();render();templateDetail(id);toast('已更新 '+result.count+' 页原版预览');break;}
case'template-page':{const [tid,page]=id.split(':'),t=state.templates.find(t=>t.id===tid);modal(t.name+' · 第'+page+'页',previewBadge(t,Number(page))+'<br><br><img class="modal-image" src="'+templateUrl(t,Number(page))+'" alt="模板第'+page+'页">',btn('template-detail','返回模板页','','',tid));break;}

case'toggle-template':await api('/api/templates/'+id+'/toggle',{});await refresh();render();break;
case'template-detail':templateDetail(id);break;
case'new-template':modal('登记模板新版本','<div class="form-grid"><p class="field-note">先在上传页面上传模板。当前需保留公司示例字段结构，校验通过后登记。</p>'+field('模板名称','tpl-name')+select('已上传文件','tpl-upload',state.uploads.map(u=>[u.id,u.name]),'')+'<div class="two-cols">'+field('封面页','tpl-cover','1','number')+field('声明页，0为不用','tpl-statement','2','number')+field('目录页','tpl-toc','3','number')+field('结束页','tpl-end','32','number')+'</div>'+field('章节页，逗号分隔','tpl-sections','4,16,22,27')+'</div>',btn('save-template','校验并登记','primary','check'),true);break;
case'save-template':await api('/api/templates',{name:val('tpl-name'),uploadId:val('tpl-upload'),cover:Number(val('tpl-cover')),statement:Number(val('tpl-statement')),toc:Number(val('tpl-toc')),end:Number(val('tpl-end')),sections:val('tpl-sections').split(/[,，]/).map(Number),enabled:true});close();await refresh();render();toast('模板已校验并登记');break;

case'new-chapter':syncOutline();chapterDialog('');break;
case'edit-chapter':chapterDialog(id);break;
case'save-chapter':{const title=val('chapter-title').trim(),summary=val('chapter-summary').trim();if(!title||title.length>40||summary.length>120)throw new Error('章节标题1～40字，摘要不超过120字');if(outline.some(c=>c.id!==id&&c.title===title))throw new Error('已有同名章节，请使用不同名称');const chapter=outline.find(c=>c.id===id);if(chapter){chapter.title=title;chapter.summary=summary;}else outline.push({id:crypto.randomUUID(),title,summary,pageIds:[]});close();render();toast('目录与章节首页将在生成时自动同步');break;}
case'chapter-up':case'chapter-down':{const i=outline.findIndex(c=>c.id===id),j=i+(a==='chapter-up'?-1:1);if(j>=0&&j<outline.length)[outline[i],outline[j]]=[outline[j],outline[i]];render();break;}
case'delete-chapter':{const c=outline.find(c=>c.id===id);if(c.pageIds.length)throw new Error('请先将页面移到其他章节');outline=outline.filter(c=>c.id!==id);render();break;}
case'edit-department':{const d=state.departments.find(d=>d.id===id);modal('修改部门名称',field('部门名称','department-edit-name',d.name,'text','maxlength="60"')+'<br><p class="field-note">改名后账号、内容和历史文件仍保持原有归属。</p>',btn('save-department-edit','保存修改','primary','check',id),true);break;}
case'save-department-edit':await api('/api/departments/'+id+'/update',{name:val('department-edit-name')});close();await refresh();render();toast('部门名称已更新');break;
case'delete-department':{const d=state.departments.find(d=>d.id===id);modal('删除部门','<div class="form-grid"><p>确定删除部门 <strong>'+E(d.name)+'</strong> 吗？</p><p class="field-note">只有未关联账号、内容页和上传文件的部门才能删除。系统管理部门保留。</p></div>',btn('close','取消')+btn('confirm-delete-department','确认删除','danger','close',id),true);break;}
case'confirm-delete-department':await api('/api/departments/'+id+'/delete',{});close();await refresh();render();toast('部门已删除');break;

case'new-department':modal('新增协作部门',field('部门名称','dep-name'),btn('save-department','保存部门','primary','check'),true);break;
case'save-department':await api('/api/departments',{name:val('dep-name')});close();await refresh();render();toast('部门已创建');break;
case'new-user':modal('创建协作账号','<div class="form-grid"><div class="two-cols">'+field('姓名','user-name')+field('登录账号','user-username')+'</div>'+field('初始密码，至少10位','user-password','','password','autocomplete="new-password"')+select('所属部门','user-department',state.departments.map(d=>[d.id,d.name]),'')+select('角色','user-role',Object.entries(roles).filter(([r])=>r!=='admin'||state.user.role==='admin'),'editor')+'</div>',btn('save-user','创建账号','primary','check'),true);break;
case'save-user':await api('/api/users',{name:val('user-name'),username:val('user-username'),password:val('user-password'),departmentId:val('user-department'),role:val('user-role')});close();await refresh();render();toast('账号已创建');break;
case'toggle-user':await api('/api/users/'+id+'/toggle',{});await refresh();render();toast('用户状态已更新');break;
}}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;ev.preventDefault();el.disabled=true;try{await action(el.dataset.action,el.dataset.id);}catch(e){toast(e.message,true);}finally{if(el.isConnected)el.disabled=false;}});
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='search'){search=el.value;const pos=el.selectionStart;render();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos);}if(el.id.startsWith('compose-'))compose[el.id.slice(8)]=el.value;if(upload&&el.id.startsWith('import-'))upload[el.id.slice(7)]=el.value;if(el.dataset.importTitle){const i=el.dataset.importTitle;edits[i]={...edits[i],title:el.value};}});
document.addEventListener('change',async ev=>{const el=ev.target;try{if(el.id==='file-input')await uploadFile(el.files[0]);if(el.id==='brand-logo-file'&&el.files[0]){const data=new FormData();data.append('logo',el.files[0]);brandConfig=await api('/api/brand/logo',data);await refresh();render();toast('公司 Logo 已更新');}if(el.id==='filter-dep'){depFilter=el.value;render();}if(el.id==='filter-status'){statusFilter=el.value;render();}if(el.id==='compose-scenario'||el.id==='compose-templateId'||el.id==='compose-title')render();if(el.id.startsWith('outline-')){const key=el.id.slice(8);compose.options[key]=el.type==='checkbox'?el.checked:el.value;render();}if(el.dataset.pageChapter)movePageTo(el.dataset.pageChapter,el.value);if(el.dataset.importTarget){const i=el.dataset.importTarget;edits[i]={...edits[i],target:el.value};render();}}catch(e){toast(e.message,true);}});
let dragging=null,draggingChapter=null;
document.addEventListener('dragstart',ev=>{const page=ev.target.closest('[data-page-id]'),chapter=ev.target.closest('[data-drag-chapter]');if(page){dragging=page.dataset.pageId;draggingChapter=null;ev.dataTransfer.setData('text/plain',dragging);page.classList.add('dragging');}else if(chapter){dragging=null;draggingChapter=chapter.dataset.dragChapter;ev.dataTransfer.setData('text/plain',draggingChapter);}});
document.addEventListener('dragend',()=>{dragging=null;draggingChapter=null;document.querySelectorAll('.dragging').forEach(el=>el.classList.remove('dragging'));});
document.addEventListener('dragover',ev=>{if(ev.target.closest('#drop-zone')||ev.target.closest('[data-chapter-drop]'))ev.preventDefault();});
document.addEventListener('drop',async ev=>{const zone=ev.target.closest('#drop-zone'),chapter=ev.target.closest('[data-chapter-drop]'),page=ev.target.closest('[data-page-id]');if(zone){ev.preventDefault();try{await uploadFile(ev.dataTransfer.files[0]);}catch(e){toast(e.message,true);}}else if(chapter&&draggingChapter){ev.preventDefault();const target=chapter.dataset.chapterDrop;if(target!==draggingChapter){const item=outline.find(c=>c.id===draggingChapter);outline=outline.filter(c=>c.id!==draggingChapter);outline.splice(outline.findIndex(c=>c.id===target),0,item);render();}}else if(chapter&&dragging&&page?.dataset.pageId!==dragging){ev.preventDefault();movePageTo(dragging,chapter.dataset.chapterDrop,page?.dataset.pageId);}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')close();if(ev.key==='Enter'&&ev.target.id==='drop-zone')$('#file-input').click();if(ev.key==='Tab'&&mr.children.length){const elements=[...mr.querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')],first=elements[0],last=elements.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'home';close();render();window.scrollTo(0,0);});
async function start(){try{const session=await api('/api/session');brandConfig=session.brand||brandConfig;document.title=(brandConfig.companyName||'示例公司')+' · PPT协作台';if(session.user){await refresh();render();return;}app.innerHTML='<div class="auth"><section class="auth-art">'+brandBlock()+'<h1>共同维护，<br>让专业有序呈现。</h1><p>从部门内容沉淀，到每一次来访介绍。<br>一套模板，一个内容库，更高效的协作方式。</p><div class="auth-line"></div></section><section class="auth-form"><form id="login-form"><div><h2>'+(session.setup?'创建管理员账号':'欢迎回到协作台')+'</h2><p style="margin-top:12px">'+(session.setup?'首次使用，请设置平台管理员账号和密码。':'使用公司分配的账号登录。')+'</p></div>'+field('账号','login-username','','text','required minlength="3" autocomplete="username"')+field('密码','login-password','','password','required minlength="'+(session.setup?10:1)+'" autocomplete="'+(session.setup?'new-password':'current-password')+'"')+'<button class="primary" type="submit">'+(session.setup?'创建并进入平台':'登录平台')+icon('arrow')+'</button><div class="auth-error" id="auth-error"></div><p>内容存储于本地服务，不调用 COM。</p></form></section></div>';$('#login-form').addEventListener('submit',async ev=>{ev.preventDefault();const b=ev.target.querySelector('button');b.disabled=true;try{await api(session.setup?'/api/setup':'/api/login',{username:val('login-username'),password:val('login-password')});await refresh();render();}catch(e){$('#auth-error').textContent=e.message;}finally{b.disabled=false;}});}catch(e){app.innerHTML='<div class="screen-error"><h2>暂时无法连接服务</h2><p>'+E(e.message)+'</p><p>请确认本地服务运行后刷新页面。</p></div>';}}
start();
